// This allows TypeScript to pick up the magic constants that's auto-generated by Forge's Vite
// plugin that tells the Electron app where to look for the Vite-bundled app code (depending on
// whether you're running in development or production).
declare const MAIN_WINDOW_VITE_DEV_SERVER_URL: string;
declare const MAIN_WINDOW_VITE_NAME: string;

declare module 'lucide-react';
declare module '@tanstack/router-plugin/vite';

interface ImportMetaEnv {
  readonly VITE_BACKEND_URL?: string;
  readonly VITE_CLOUD_API_URL?: string;
  readonly VITE_CLOUD_AUTH_URL?: string;
}

interface ImportMeta {
  readonly env?: ImportMetaEnv;
}

interface ElectronOAuthApi {
  onOAuthCallback: (
    callback: (data: { provider?: string; token: string; user: any }) => void
  ) => () => void;
  startOAuth: (
    provider: string
  ) => Promise<{ error?: string; port?: number; success: boolean }>;
}

interface ElectronWindowApi {
  onWindowStateChange: (
    callback: (data: { isMaximized: boolean }) => void
  ) => () => void;
}

interface UpdateProgressData {
  bytes: number;
  total: number;
  percent: number;
}

interface ElectronUpdaterApi {
  startDownload: (data: {
    url: string;
    fileName: string;
  }) => Promise<{ error?: string; filePath?: string; success: boolean }>;
  openInstaller: (
    filePath: string
  ) => Promise<{ error?: string; success: boolean }>;
  onProgress: (callback: (data: UpdateProgressData) => void) => () => void;
  onComplete: (callback: (data: { filePath: string }) => void) => () => void;
  onError: (callback: (data: { error: string }) => void) => () => void;
}

interface Window {
  electronOAuth?: ElectronOAuthApi;
  electronWindow?: ElectronWindowApi;
  electronUpdater?: ElectronUpdaterApi;
}
